private void fireChange(String propertyName,Object oldValue,Object newValue){
  PropertyChangeEvent evt=new PropertyChangeEvent(this,propertyName,oldValue,newValue);
  try {
    for (  PropertyChangeListener l : listeners.get(propertyName)) {
      l.propertyChange(evt);
    }
    for (  PropertyChangeListener l : listeners.get(null)) {
      l.propertyChange(evt);
    }
  } catch (NullPointerException e) {
    // Log or ignore; null listeners are expected and should not break execution
  }
}
